1	package com.fream.back.domain.order.repository;
2	
3	import com.fream.back.domain.order.dto.OrderBidResponseDto;
4	import com.fream.back.domain.order.dto.OrderBidStatusCountDto;
5	import com.fream.back.domain.order.entity.BidStatus;
6	import com.fream.back.domain.order.entity.QOrder;
7	import com.fream.back.domain.order.entity.QOrderBid;
8	import com.fream.back.domain.product.entity.QProduct;
9	import com.fream.back.domain.product.entity.QProductColor;
10	import com.fream.back.domain.product.entity.QProductImage;
11	import com.fream.back.domain.product.entity.QProductSize;
12	import com.fream.back.domain.shipment.entity.QOrderShipment;
13	import com.fream.back.domain.user.entity.QUser;
14	import com.querydsl.core.BooleanBuilder;
15	import com.querydsl.core.Tuple;
16	import com.querydsl.core.types.Projections;
17	import com.querydsl.jpa.impl.JPAQueryFactory;
18	import lombok.RequiredArgsConstructor;
19	import org.springframework.data.domain.Page;
20	import org.springframework.data.domain.PageImpl;
21	import org.springframework.data.domain.Pageable;
22	import org.springframework.stereotype.Repository;
23	import org.springframework.util.StringUtils;
24	
25	import java.util.Collections;
26	import java.util.List;
27	import java.util.Map;
28	import java.util.stream.Collectors;
29	
30	/**
31	 * 주문 입찰 저장소 구현체
32	 */
33	@Repository
34	@RequiredArgsConstructor
35	public class OrderBidRepositoryImpl implements OrderBidRepositoryCustom {
36	    private final JPAQueryFactory queryFactory;
37	
38	    @Override
39	    public Page<OrderBidResponseDto> findOrderBidsByFilters(String email, String bidStatus, String orderStatus, Pageable pageable) {
40	        QOrderBid orderBid = QOrderBid.orderBid;
41	        QOrder order = QOrder.order;
42	        QProductSize productSize = QProductSize.productSize;
43	        QProductColor productColor = QProductColor.productColor;
44	        QProduct product = QProduct.product;
45	        QProductImage productImage = QProductImage.productImage;
46	        QOrderShipment orderShipment = QOrderShipment.orderShipment;
47	        QUser user = QUser.user;
48	
49	        // 조건 빌더 생성
50	        BooleanBuilder whereBuilder = new BooleanBuilder();
51	
52	        // 이메일 조건 추가
53	        if (StringUtils.hasText(email)) {
54	            whereBuilder.and(user.email.eq(email));
55	        }
56	
57	        // 입찰 상태 조건 추가
58	        if (StringUtils.hasText(bidStatus)) {
59	            whereBuilder.and(orderBid.status.stringValue().eq(bidStatus));
60	        }
61	
62	        // 주문 상태 조건 추가
63	        if (StringUtils.hasText(orderStatus)) {
64	            whereBuilder.and(order.status.stringValue().eq(orderStatus));
65	        }
66	
67	        // Main Query
68	        List<OrderBidResponseDto> content = queryFactory
69	                .select(Projections.constructor(
70	                        OrderBidResponseDto.class,
71	                        orderBid.id,
72	                        product.id,
73	                        product.name,
74	                        product.englishName,
75	                        productSize.size,
76	                        productColor.colorName,
77	                        productImage.imageUrl,
78	                        orderBid.bidPrice,
79	                        orderBid.status.stringValue(),
80	                        order.status.stringValue(),
81	                        orderShipment.status.stringValue(),
82	                        orderBid.createdDate,
83	                        orderBid.modifiedDate
84	                ))
85	                .from(orderBid)
86	                .join(orderBid.user, user)
87	                .join(orderBid.productSize, productSize)
88	                .join(productSize.productColor, productColor)
89	                .join(productColor.product, product)
90	                .join(productColor.thumbnailImage, productImage)
91	                .leftJoin(orderBid.order, order)
92	                .leftJoin(order.orderShipment, orderShipment)
93	                .where(whereBuilder)
94	                .offset(pageable.getOffset())
95	                .limit(pageable.getPageSize())
96	                .fetch();
97	
98	        // Count Query
99	        Long total = queryFactory
100	                .select(orderBid.id.count())
101	                .from(orderBid)
102	                .join(orderBid.user, user)
103	                .leftJoin(orderBid.order, order)
104	                .where(whereBuilder)
105	                .fetchOne();
106	
107	        return new PageImpl<>(content, pageable, total != null ? total : 0L);
108	    }
109	
110	    @Override
111	    public OrderBidStatusCountDto countOrderBidsByStatus(String email) {
112	        QOrderBid orderBid = QOrderBid.orderBid;
113	
114	        // 대기 중 상태 개수 조회
115	        Long pendingCount = queryFactory
116	                .select(orderBid.count())
117	                .from(orderBid)
118	                .where(orderBid.status.eq(BidStatus.PENDING)
119	                        .and(orderBid.user.email.eq(email)))
120	                .fetchOne();
121	
122	        // 매칭 완료 상태 개수 조회
123	        Long matchedCount = queryFactory
124	                .select(orderBid.count())
125	                .from(orderBid)
126	                .where(orderBid.status.eq(BidStatus.MATCHED)
127	                        .and(orderBid.user.email.eq(email)))
128	                .fetchOne();
129	
130	        // 취소 또는 완료 상태 개수 조회
131	        Long cancelledOrCompletedCount = queryFactory
132	                .select(orderBid.count())
133	                .from(orderBid)
134	                .where(orderBid.status.in(
135	                                BidStatus.CANCELLED, BidStatus.COMPLETED)
136	                        .and(orderBid.user.email.eq(email)))
137	                .fetchOne();
138	
139	        // null 값 처리
140	        pendingCount = pendingCount != null ? pendingCount : 0L;
141	        matchedCount = matchedCount != null ? matchedCount : 0L;
142	        cancelledOrCompletedCount = cancelledOrCompletedCount != null ? cancelledOrCompletedCount : 0L;
143	
144	        return new OrderBidStatusCountDto(pendingCount, matchedCount, cancelledOrCompletedCount);
145	    }
146	
